-- 128: Original BrillaPrep WASSCE Applied Electricity syllabus evidence beta questions, part 1.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_001', 'topic_was_elect_1', 'subj_wassce_elect_app', 'exam_wassce', 'What should be done first before working on a mains electrical circuit?', 'multiple_choice', '["A. Isolate the supply and verify that the circuit is de-energised","B. Touch a conductor to test it by sensation","C. Replace the fuse while current is flowing","D. Assume an open switch guarantees isolation"]', 'A', 'Safe isolation requires disconnection, prevention of unintended reconnection and verification with suitable test equipment before conductors are handled. Therefore the correct answer is A: Isolate the supply and verify that the circuit is de-energised.', 'easy', 1, 1, 90, 'st_was_elect_1', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_002', 'topic_was_elect_1', 'subj_wassce_elect_app', 'exam_wassce', 'What is the SI unit of electric current?', 'multiple_choice', '["A. Volt","B. Ampere","C. Ohm","D. Watt"]', 'B', 'Current is the rate of flow of electric charge and is measured in amperes, while voltage, resistance and power use different units. Therefore the correct answer is B: Ampere.', 'medium', 2, 2, 90, 'st_was_elect_1', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_003', 'topic_was_elect_1', 'subj_wassce_elect_app', 'exam_wassce', 'A 12 V device draws 2 A. What electrical power does it use?', 'multiple_choice', '["A. 6 W","B. 10 W","C. 24 W","D. 48 W"]', 'C', 'Electrical power in a direct-current resistive load is P = VI, so 12 multiplied by 2 gives 24 watts. Therefore the correct answer is C: 24 W.', 'hard', 1, 1, 90, 'st_was_elect_1', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_004', 'topic_was_elect_1', 'subj_wassce_elect_app', 'exam_wassce', 'What does resistance describe?', 'multiple_choice', '["A. The rate of using electrical energy only","B. The amount of charge stored in every source","C. The magnetic direction of a compass","D. Opposition to electric current flow"]', 'D', 'Resistance relates voltage to current and is measured in ohms; material, length, cross-sectional area and temperature can affect it. Therefore the correct answer is D: Opposition to electric current flow.', 'easy', 2, 2, 90, 'st_was_elect_1', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_005', 'topic_was_elect_1', 'subj_wassce_elect_app', 'exam_wassce', 'Why must a person avoid using water on energised electrical equipment?', 'multiple_choice', '["A. Water can create conductive paths and increase shock or fault risk","B. Water always raises insulation resistance","C. It safely isolates every live conductor","D. It guarantees that protective devices cannot operate"]', 'A', 'Ordinary water and contaminants may conduct current, exposing people and equipment to shock, short-circuit and arc hazards. Therefore the correct answer is A: Water can create conductive paths and increase shock or fault risk.', 'medium', 3, 3, 90, 'st_was_elect_1', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_006', 'topic_was_elect_2', 'subj_wassce_elect_app', 'exam_wassce', 'Two resistors of 4 Ω and 6 Ω are connected in series. What is their total resistance?', 'multiple_choice', '["A. 2.4 Ω","B. 10 Ω","C. 5 Ω","D. 24 Ω"]', 'B', 'Series resistances add because the same current passes through each component, giving 4 plus 6 equals 10 ohms. Therefore the correct answer is B: 10 Ω.', 'hard', 2, 2, 90, 'st_was_elect_2', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_007', 'topic_was_elect_2', 'subj_wassce_elect_app', 'exam_wassce', 'What quantity is the same through all components in a series circuit?', 'multiple_choice', '["A. Voltage across each component","B. Resistance of each component","C. Current","D. Power used by each component"]', 'C', 'A series path has no branch, so the same current flows through every component while supply voltage is divided among them. Therefore the correct answer is C: Current.', 'easy', 1, 1, 90, 'st_was_elect_2', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_008', 'topic_was_elect_2', 'subj_wassce_elect_app', 'exam_wassce', 'Two identical resistors are connected in parallel. How does their equivalent resistance compare with one resistor?', 'multiple_choice', '["A. It is twice the resistance","B. It is unchanged","C. It is zero for every resistor value","D. It is half the resistance of one resistor"]', 'D', 'For two equal parallel resistors, conductances add, producing an equivalent resistance R divided by 2. Therefore the correct answer is D: It is half the resistance of one resistor.', 'medium', 2, 2, 90, 'st_was_elect_2', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_009', 'topic_was_elect_2', 'subj_wassce_elect_app', 'exam_wassce', 'What does Kirchhoff’s current law state at a junction?', 'multiple_choice', '["A. Total current entering equals total current leaving","B. All branch voltages must be zero","C. Resistance is independent of material","D. Power can be created at a junction"]', 'A', 'The law follows conservation of charge: charge cannot continually accumulate at an ideal circuit node. Therefore the correct answer is A: Total current entering equals total current leaving.', 'hard', 1, 1, 90, 'st_was_elect_2', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_010', 'topic_was_elect_2', 'subj_wassce_elect_app', 'exam_wassce', 'A 6 Ω resistor carries 3 A. What is the voltage across it?', 'multiple_choice', '["A. 2 V","B. 18 V","C. 9 V","D. 36 V"]', 'B', 'Ohm’s law gives V = IR. Multiplying 3 amperes by 6 ohms gives a potential difference of 18 volts. Therefore the correct answer is B: 18 V.', 'easy', 3, 3, 90, 'st_was_elect_2', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to published WAEC Ghana Applied Electricity evidence; not official WAEC examination material.', 'https://waecgh.org/wp-content/uploads/2023/12/Technical17.pdf', 0, 1 FROM questions WHERE id BETWEEN 'q_was_elect_b001_001' AND 'q_was_elect_b001_010';
